/* SplitText shim - not the GreenSock plugin.
   The bundled SplitText 3.11.2 was a Club GreenSock membership plugin and is not
   licensed for use on this site, so it was removed. The theme's main.js constructs
   a SplitText and reads .split()/.words/.lines/.chars, which this shim satisfies as a
   no-op: text renders normally, the character reveal animation simply does not run. */
(function (w) {
  function SplitText(el) {
    this.elements = [el]; this.words = []; this.lines = []; this.chars = [];
    this.target = el;
  }
  SplitText.prototype.split = function () { return this; };
  SplitText.prototype.revert = function () { return this; };
  SplitText.prototype.merge = function () { return this; };
  w.SplitText = SplitText; w.gsap = w.gsap || { registerPlugin: function () {} };
})(window);
